header('Content-Type: application/json; charset=utf-8');require_once __DIR__.'/conexion.php';$data=json_decode(file_get_contents('php://input'),true)??[];$ids=array_values(array_unique(array_filter(array_map('intval',$data['ids']??[]),fn($x)=>$x>0)));if(count($ids)<2||count($ids)>3){http_response_code(422);echo json_encode(['success'=>false,'message'=>'Selecciona entre 2 y 3 productos.']);exit;}$in=implode(',',array_fill(0,count($ids),'?'));$q=$pdo->prepare("SELECT p.id,p.nombre,p.descripcion,p.precio,p.stock,p.categoria,d.marca,d.garantia,d.especificaciones FROM productos p LEFT JOIN producto_detalles d ON d.producto_id=p.id WHERE p.activo=1 AND p.id IN ($in)");$q->execute($ids);echo json_encode(['success'=>true,'products'=>$q->fetchAll()],JSON_UNESCAPED_UNICODE);
